package dev.rinorsi.editor.registry;

import com.google.gson.*;
import dev.rinorsi.editor.ComponentValidation;
import java.nio.file.*;
import java.util.*;
import net.minecraft.SharedConstants;
import net.minecraft.core.RegistryAccess;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.server.Bootstrap;

/** Snapshot is generated by live codec derivation, not used as a production schema source. */
public final class ComponentSchemaTest {
    // Requested UI scope (>40 because all explicitly requested components are included).
    public static final List<String> SCOPE = Arrays.stream(("custom_name item_name lore rarity enchantments stored_enchantments enchantment_glint_override tooltip_display tooltip_style item_model custom_model_data damage max_damage max_stack_size unbreakable repair_cost repairable damage_resistant attribute_modifiers food consumable use_remainder use_cooldown equippable tool weapon blocks_attacks potion_contents suspicious_stew_effects dyed_color trim banner_patterns base_color container bundle_contents container_loot block_entity_data entity_data bucket_entity_data custom_data profile firework_explosion fireworks jukebox_playable instrument glider death_protection enchantable can_place_on can_break lodestone_tracker map_color map_id map_decorations written_book_content writable_book_content").split(" ")).sorted().toList();
    public static RegistryAccess bootstrap() {
        SharedConstants.tryDetectVersion(); Bootstrap.bootStrap();
        var lookup = net.minecraft.data.registries.VanillaRegistries.createLookup();
        BuiltInRegistries.DATA_COMPONENT_INITIALIZERS.build(lookup).forEach(p -> p.apply());
        var builtins = RegistryAccess.fromRegistryOfRegistries(BuiltInRegistries.REGISTRY);
        return new RegistryAccess() {
            @Override public <E> Optional<net.minecraft.core.Registry<E>> lookup(net.minecraft.resources.ResourceKey<? extends net.minecraft.core.Registry<? extends E>> key) { return builtins.lookup(key); }
            @Override public java.util.stream.Stream<RegistryAccess.RegistryEntry<?>> registries() { return builtins.registries(); }
            @Override public <V> net.minecraft.resources.RegistryOps<V> createSerializationContext(com.mojang.serialization.DynamicOps<V> ops) { return lookup.createSerializationContext(ops); }
        };
    }
    private static int checks;
    public static void main(String[] args) throws Exception {
        var access = bootstrap(); var entries = new JsonArray();
        for (String id : SCOPE) {
            var derived = ComponentSchema.derive(id, access); entries.add(derived.entry());
            check(derived.entry().has("coverage"), "coverage " + id);
            check(derived.entry().getAsJsonArray("fields").size() == 1, "root " + id);
            check(derived.entry().toString().length() < 23000, "row budget " + id);
            for (var prototype : derived.entry().getAsJsonArray("prototype_examples")) {
                var request = new JsonObject(); request.addProperty("component", id); request.add("value", prototype.getAsJsonObject().get("value"));
                check(ComponentValidation.validate(request, access).get("ok").getAsBoolean(), "real prototype parses " + id);
            }
        }
        var pages = RegistryPages.split("component_schema", "test", entries);
        int rows = 0;
        for (var page : pages) {
            check(page.toString().length() <= RegistryPages.MAX_CHARS, "real schema wire page budget");
            check(page.get("offset").getAsInt() == rows, "real schema contiguous offsets");
            rows += page.getAsJsonArray("entries").size();
        }
        check(rows == SCOPE.size() && pages.getLast().get("done").getAsBoolean(), "all schema rows paginated");
        var stack = ComponentSchema.derive("max_stack_size", access);
        check(stack.root().json.get("min").getAsInt() == 1 && stack.root().json.get("max").getAsInt() == 99, "stack range from actual codec");
        check(!ComponentSchema.errors(stack, new JsonPrimitive(100), access).isEmpty(), "stack bad boundary has path");
        var food = ComponentSchema.derive("food", access);
        check(food.root().fields.containsKey("nutrition") && food.root().fields.containsKey("saturation"), "record fields extracted");
        check(food.root().fields.get("can_always_eat").json.get("default").getAsBoolean() == false, "actual optional default extracted");
        var errors = ComponentSchema.errors(food, JsonParser.parseString("""
                {"nutrition":-1,"saturation":"invalid"}
                """), access);
        check(errors.toString().contains("$.nutrition") && errors.toString().contains("$.saturation"), "per-path independent failures");
        var enchants = ComponentSchema.derive("enchantments", access);
        check(enchants.root().element.json.get("max").getAsInt() == 255, "enchantment level actual maximum");
        var missing = ComponentSchema.errors(food, new JsonObject(), access);
        check(missing.toString().contains("required"), "missing required field path");
        var badFood = new JsonObject(); badFood.addProperty("component", "food"); badFood.add("value", JsonParser.parseString("""
                {"nutrition":-1,"saturation":"invalid"}
                """));
        badFood.addProperty("requestId", "schema-path-test");
        var detailed = ComponentSchemaValidation.validate(badFood, access);
        check(!detailed.get("ok").getAsBoolean() && detailed.get("path_precision").getAsString().equals("field"), "helper preserves whole-codec failure");
        check(detailed.getAsJsonArray("errors").toString().contains("$.nutrition"), "helper returns real field path");
        var legacy = ComponentValidation.validate(badFood, access);
        var withoutDetails = detailed.deepCopy(); withoutDetails.remove("errors"); withoutDetails.remove("path_precision");
        check(legacy.equals(withoutDetails), "legacy validation fields unchanged");
        var badTool = new JsonObject(); badTool.addProperty("component", "tool"); badTool.add("value", JsonParser.parseString("""
                {"rules":[{"blocks":"minecraft:stone","speed":-1}]}
                """));
        check(ComponentSchemaValidation.validate(badTool, access).getAsJsonArray("errors").toString().contains("$.rules[0].speed"), "nested list path from exact field codec");
        var badSnbt = new JsonObject(); badSnbt.addProperty("component", "custom_data"); badSnbt.addProperty("snbt", "{broken:}");
        check(ComponentSchemaValidation.validate(badSnbt, access).get("path_precision").getAsString().equals("component"), "SNBT parser error never assigned fabricated field path");
        var snapshot = new JsonObject(); snapshot.addProperty("mc_version", "26.1.2"); snapshot.addProperty("schema_version", ComponentSchema.VERSION); snapshot.add("components", entries);
        var findings = new JsonArray();
        captureProbe(findings, "tool", "$.rules[0].speed", "data.js numeric schema has no min; core.validateValue allows 0", JsonParser.parseString("""
                {"rules":[{"blocks":"minecraft:stone","speed":0}]}
                """), access);
        captureProbe(findings, "use_cooldown", "$.seconds", "data.js numeric schema has no min; core.validateValue allows 0", JsonParser.parseString("""
                {"seconds":0}
                """), access);
        var book = new JsonObject(); book.addProperty("title", "a".repeat(33)); book.addProperty("author", "test");
        captureProbe(findings, "written_book_content", "$.title", "data.js title string has no max length; core.validateValue allows 33 chars", book, access);
        captureProbe(findings, "max_stack_size", "$", "core.validateValue rejects fractional values for t:int", new JsonPrimitive(1.5), access);
        captureProbe(findings, "fireworks", "$.flight_duration", "data.js int min:0/max:255; core rejects 256", JsonParser.parseString("""
                {"flight_duration":256}
                """), access);
        var manySlots = new JsonArray();
        for (int i = 0; i < 257; i++) manySlots.add(JsonParser.parseString("""
                {"slot":0,"item":{"id":"minecraft:stone"}}
                """));
        captureProbe(findings, "container", "$", "data.js list max:256; core rejects 257 entries (including duplicate slots)", manySlots, access);
        Path path = Path.of("docs/component-schema-26.1.2.json");
        if (args.length > 0 && args[0].equals("--write-snapshot")) Files.writeString(path, new GsonBuilder().setPrettyPrinting().disableHtmlEscaping().create().toJson(snapshot) + System.lineSeparator());
        else {
            if (args.length > 1 && args[0].equals("--snapshot")) path = Path.of(args[1]);
            JsonElement expected = JsonParser.parseString(Files.readString(path));
            // Compare wire JSON, not Gson Float/Double backing classes (Float.MAX_VALUE
            // widens differently from its shortest serialized decimal representation).
            JsonElement wireSnapshot = JsonParser.parseString(snapshot.toString());
            if (!expected.equals(wireSnapshot)) {
                Path actual = Path.of("logs/backend-g/schema-drift-actual.json");
                Files.createDirectories(actual.getParent());
                Files.writeString(actual, new GsonBuilder().setPrettyPrinting().create().toJson(snapshot));
            }
            check(expected.equals(wireSnapshot), "live derivation differs from snapshot; review codec drift, then explicitly regenerate --write-snapshot");
        }
        if (args.length > 1 && args[0].equals("--write-snapshot")) {
            var receipt = new JsonObject(); receipt.add("field_validation", detailed); receipt.add("nested_validation", ComponentSchemaValidation.validate(badTool, access));
            receipt.add("boundary_findings", findings);
            receipt.addProperty("checks", checks); receipt.addProperty("status", "PASSED");
            Files.writeString(Path.of(args[1]), new GsonBuilder().setPrettyPrinting().create().toJson(receipt));
        }
        System.out.println("PASS ComponentSchemaTest " + checks + " checks; " + SCOPE.size() + " live component schemas, real defaults/ranges/path diagnostics and snapshot drift");
    }
    private static void captureProbe(JsonArray out, String id, String path, String ui, JsonElement input, RegistryAccess access) {
        var codec = ComponentValidation.type(id).codec(); var ops = access.createSerializationContext(com.mojang.serialization.JsonOps.INSTANCE);
        var result = codec.parse(ops, input); var row = new JsonObject(); row.addProperty("component", "minecraft:" + id); row.addProperty("path", path);
        row.addProperty("ui_observation", ui); row.addProperty("codec_ok", result.isSuccess());
        result.error().ifPresent(e -> row.addProperty("codec_error", e.message().substring(0, Math.min(1000, e.message().length()))));
        if (result.isSuccess()) {
            @SuppressWarnings("unchecked") var typed = (com.mojang.serialization.Codec<Object>) codec;
            var normalized = typed.encodeStart(ops, result.getOrThrow()).getOrThrow();
            if (normalized.toString().length() < 1800) row.add("normalized", normalized);
        }
        out.add(row);
    }
    private static void check(boolean value, String message) { if (!value) throw new AssertionError(message); checks++; }
}
